INSERT INTO `courses` VALUES (138933, 937766, 'SOCW', '4012', 2020, 'Diversity', 'An analysis of the structure, culture, and social processes of ethnicity, gender, sexual\r\norientation, social economic status, and religious groups in America. Prerequisite: Junior\r\nstanding or permission of instructor and/or Program Coordinator. Formerly SOCL 4012', 3.0000, 3.0000, 3.0000, 0, NULL, 0, 0);
INSERT INTO `courses` VALUES (138934, 937766, 'SOCL', '412', 2020, 'Diversity', 'An analysis of the structure, culture, and social processes of ethnicity, gender, sexual\r\norientation, social economic status, and religious groups in America. Prerequisite: Junior\r\nstanding or permission of instructor and/or Program Coordinator. Formerly SOCL 4012', 3.0000, 3.0000, 3.0000, 1, NULL, 0, 0), (138935, 613601, 'PHYS', '203', 2020, 'General Physics I', 'This is a trigonometry-based physics class involving the principles and laws of kinematics, forces, energy, momentum, linear and rotation motion, and statics. Selected topics may include fluids, vibrations, sound, kinetic theory, and heat. Prerequisite: MATH 1012 or 1013. Students may receive credit toward degree in only one of PHYS 2007, PHYS 2003, and PSCI 1001. <br><br>\r\n\r\n\r\nLCCN: CPHY 2113', 3.0000, 3.0000, 3.0000, 1, NULL, 0, 0), (138936, 9759778, 'GEOS', '1001', 2020, 'Earth Science', 'A study of the physical processes of the Earth system, including such topics as minerals,\r\nthe rock cycle, the water cycle, volcanoes, earthquakes, weathering, plate tectonics,\r\noceans, and the atmosphere. Students may not receive credit toward degree in both GEOS 1001 and GEOL 1001.\r\n\r\nPrerequisites: None.', 3.0000, 3.0000, 3.0000, 0, NULL, 0, 0), (138941, 89499, 'MATH', '1016', 2020, 'Elementary Statistics', 'Descriptive statistics; probability calculations; discrete and continuous probability\r\ndistributions (including the binomial and Poisson distributions, the normal and\r\nStudent-t distributions); interval estimations, hypothesis testing, linear regression and\r\ncorrelation. Not applicable to a major or minor in computer science.\r\nPrerequisite(s): A grade of C or better in MATH 1009, Math 1011, Math 1013 or Math\r\n1014.<br><br>\r\n\r\nLCCN: CMAT 1303', 3.0000, 3.0000, 3.0000, 0, NULL, 0, 0), (138942, 730398, 'KINS', '221', 2020, 'Concepts of Wellness', 'Survey of the components of human wellness with emphasis on techniques and methods of instruction to enhance wellness. Prerequisite: Kinesiology majors only.', 3.0000, 3.0000, 3.0000, 1, NULL, 0, 0), (138943, 730398, 'KINS', '2021', 2020, 'Concepts of Wellness', 'Survey of the components of human wellness with emphasis on techniques and methods of instruction to enhance wellness. Prerequisite: Kinesiology majors only.', 3.0000, 3.0000, 3.0000, 0, NULL, 0, 0), (138944, 730398, 'H&HP', '221', 2020, 'Concepts of Wellness', 'Survey of the components of human wellness with emphasis on techniques and methods of instruction to enhance wellness. Prerequisite: Kinesiology majors only.', 3.0000, 3.0000, 3.0000, 1, NULL, 0, 0), (138945, 553209, 'KINS', '417', 2020, 'School and Multicultural Health', 'School and cultural health problems for school aged children and current programs of prevention and protection against disease. Prerequisite: junior standing. Education majors only.', 3.0000, 3.0000, 3.0000, 1, NULL, 0, 0), (138946, 553209, 'KINS', '4017', 2020, 'School and Multicultural Health', 'School and cultural health problems for school aged children and current programs of prevention and protection against disease. Prerequisite: junior standing. Education majors only.', 3.0000, 3.0000, 3.0000, 0, NULL, 0, 0), (138947, 406394, 'BIOL', '3002', 2020, 'Principles of Ecology', 'The basic principles of relationships between organisms and the environment. Three hours lecture and three hours laboratory per week. Prerequisites: C or better in 1022, 1023. (Formerly 3003, 3004)<br><br>\r\n\r\n\r\nLCCN: CECO 4124', 4.0000, 4.0000, 4.0000, 0, NULL, 0, 0), (138948, 868182, 'BIOL', '3004', 2020, 'Principles of Ecology Laboratory', 'A laboratory course to accompany 3003. Three hours laboratory. Field trip fee required. Prerequisite: Credit or registration in 3003.', 1.0000, 1.0000, 1.0000, 1, NULL, 0, 0), (138949, 509710, 'CINS', '3040', 2020, 'Networks and Data Communications', 'Concepts of data communications and networks and their impact on the business enterprise; issues pertaining to design, development, and implementation; hands-on experience with a network. Prerequisite: CINS 2020 or CSCI 2000. F, Sp', 3.0000, 3.0000, 3.0000, 0, NULL, 0, 0), (138950, 509710, 'CINS', '340', 2020, 'Networks and Data Communications', 'Concepts of data communications and networks and their impact on the business enterprise; issues pertaining to design, development, and implementation; hands-on experience with a network. Prerequisite: CINS 2020 or CSCI 2000. F, Sp', 3.0000, 3.0000, 3.0000, 1, NULL, 0, 0), (138951, 630974, 'CSCI', '298', 2020, 'Ethical and Professional Issues in Computing', 'Presentation of current topics in the field of computer science with special emphasis on ethics. Prerequisites: CSCI 2073', 2.0000, 2.0000, 2.0000, 1, NULL, 0, 0), (138952, 630974, 'CSCI', '2098', 2020, 'Ethical and Professional Issues in Computing', 'Presentation of current topics in the field of computer science with special emphasis on ethics. Prerequisites: CSCI 2073', 2.0000, 2.0000, 2.0000, 0, NULL, 0, 0), (138953, 2725748, 'MLSC', '4060', 2020, 'Medical Laboratory Science Professionalism', 'Lecture course focusing on professionalism in medical laboratory science, with emphasis on participation and service in professional organizations. Utilization of study tools in preparation for the Board of Certification examination will be explored. MLSC majors only.', 1.0000, 1.0000, 1.0000, 0, NULL, 0, 0), (138954, 52273, 'KINS', '411', 2020, 'Care and Prevention of Athletic Injuries', 'The prevention and emergency care of athletic injuries. Prerequisites: KINS 2011 and\r\njunior standing. Kinesiology majors only.', 3.0000, 3.0000, 3.0000, 1, NULL, 0, 0), (138955, 832657, 'COMM', '4080', 2020, 'Digital Cinema', 'Theory and techniques of video production from conception to completion, for a variety of mass communications applications. One hour lecture, four hours studio. Additional course fee. Prerequisite: Senior standing, graduate stan